package org.vechain.indexer.utils

import org.junit.jupiter.api.Test
import org.junit.jupiter.params.ParameterizedTest
import org.junit.jupiter.params.provider.Arguments
import org.junit.jupiter.params.provider.MethodSource
import org.vechain.indexer.contracts.specifications.ContractSpecification
import org.vechain.indexer.contracts.specifications.Contracts
import strikt.api.expectThat
import strikt.assertions.isEqualTo
import strikt.assertions.isTrue

class ContractUtilsTest {

    @Test
    fun getFunctionSignature() {
        val canonicalName = "baz(uint32,bool)"

        val signature = ContractUtils.getFunctionSignature(canonicalName)

        expectThat(signature).isEqualTo("cdcd77c0")
    }

    @Test
    fun getEventSignature() {
        val canonicalName = "Deposit(address,hash256,uint256)"

        val signature = ContractUtils.getEventSignature(canonicalName)

        expectThat(signature)
            .isEqualTo("50cb9fe53daa9737b786ab3646f04d0150dc50ef4e75f59509d83667ad5adb20")
    }

    companion object {
        @JvmStatic
        fun contractData() =
            listOf(
                Arguments.of(
                    Contracts.ERC20,
                    ""
                ),
                Arguments.of(
                    Contracts.ERC721,
                    ""
                ),
                Arguments.of(
                    Contracts.ERC1155,
                    ""
                ),
                Arguments.of(
                    Contracts.VIP210,
                    ""
                ),
                Arguments.of(
                    Contracts.VIP180,
                    ""
                ),
                Arguments.of(
                    Contracts.VIP181,
                    ""
                ),
            )
    }

    @ParameterizedTest
    @MethodSource("contractData")
    fun `is contract type`(specification: ContractSpecification, rawData: String) {
        val isContractType = ContractUtils.isContractType(specification, rawData)

        expectThat(isContractType)
            .describedAs {
                " - Contract was not identified: ${specification.javaClass.simpleName} "
            }
            .isTrue()
    }
}
